(function(root){
function parseCSV(source){let rows=[],row=[],field='',quoted=false;source=source.replace(/^\uFEFF/,'');for(let i=0;i<source.length;i++){let c=source[i];if(c==='"'){if(quoted&&source[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field='';if(c==='\r'&&source[i+1]==='\n')i++}else field+=c}if(quoted)throw Error('The CSV contains an unclosed quoted field.');if(field||row.length){row.push(field);rows.push(row)}return rows}
function catalog(source){const table=parseCSV(source);const header=(table.shift()||[]).map(v=>v.trim().toLowerCase());if(!['title','type','release_year'].every(k=>header.includes(k)))throw Error('CSV needs title, type, and release_year columns. Optional: country, listed_in, rating.');let skipped=0;const rows=table.flatMap((r,i)=>{const get=k=>(r[header.indexOf(k)]||'').trim(),year=Number(get('release_year'));if(!get('title')||!['Movie','TV Show'].includes(get('type'))||!Number.isInteger(year)||year<1880||year>2100){skipped++;return []}return [{id:'row-'+i,title:get('title'),type:get('type'),releaseYear:year,country:get('country'),genres:get('listed_in'),rating:get('rating')} ]});if(!rows.length)throw Error('No valid catalogue rows found.');return{rows,skipped}}
const tokens=value=>String(value||'').split(',').map(v=>v.trim()).filter(Boolean);
function groups(rows,key){const counts=new Map;for(const row of rows)for(const value of new Set(key(row)))if(value)counts.set(value,(counts.get(value)||0)+1);return [...counts].map(([name,count])=>({name,count})).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name))}
function filter(rows,{query='',type='All',country='All',year=0}={}){return rows.filter(r=>(!query||[r.title,r.genres].some(v=>v.toLowerCase().includes(query.toLowerCase())))&&(type==='All'||r.type===type)&&(country==='All'||tokens(r.country).includes(country))&&r.releaseYear>=year)}
const api={parseCSV,catalog,tokens,groups,filter};if(typeof module!=='undefined')module.exports=api;else root.CatalogAnalytics=api;
})(typeof window!=='undefined'?window:globalThis);
